"""Generate the Unicode 16 classifier; run with a Unicode 16 CPython."""
import pathlib
import unicodedata

assert unicodedata.unidata_version == "16.0.0"
ranges = []
start = None
for cp in range(0x110001):
    excluded = cp < 0x110000 and not chr(cp).isprintable()
    if excluded and start is None:
        start = cp
    elif not excluded and start is not None:
        ranges.append((start, cp - 1))
        start = None
pathlib.Path(__file__).with_name("src").joinpath("unicode16.rs").write_text(
    "// Generated by gen_unicode.py: CPython Unicode 16.0.0 isprintable.\n"
    "pub const NONPRINTABLE: &[(u32, u32)] = &[\n" +
    "".join(f"    (0x{a:x}, 0x{b:x}),\n" for a, b in ranges) + "];\n")
